def run(_context):
    cam = mb.get_cam()
    setup = None
    for s in cam.setups:
        if s.name == "Setup1":
            setup = s
    total = 0.0
    for op in setup.allOperations:
        mt = cam.machiningTime(op, 100.0, 5000.0, 15.0)
        t = mt.machiningTime  # seconds
        total += t
        print(op.name, round(t/60, 2), "min")
    print("TOTAL", round(total/60, 2), "min (+ toolchanges)")
